create table if not exists public.projects (
  id bigint generated by default as identity primary key,
  title text not null,
  subtitle text default '',
  description text default '',
  technologies text[] default '{}',
  results text[] default '{}',
  github text default '',
  demo text default '',
  image text default '',
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);
alter table public.projects enable row level security;
drop policy if exists "Public read projects" on public.projects;
create policy "Public read projects" on public.projects for select to anon, authenticated using (true);
drop policy if exists "Authenticated insert projects" on public.projects;
create policy "Authenticated insert projects" on public.projects for insert to authenticated with check (true);
drop policy if exists "Authenticated update projects" on public.projects;
create policy "Authenticated update projects" on public.projects for update to authenticated using (true) with check (true);
drop policy if exists "Authenticated delete projects" on public.projects;
create policy "Authenticated delete projects" on public.projects for delete to authenticated using (true);
grant select on public.projects to anon;
grant select, insert, update, delete on public.projects to authenticated;

create table if not exists public.site_content (
  id integer primary key default 1 check (id = 1),
  content jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
alter table public.site_content enable row level security;
drop policy if exists "Public read site content" on public.site_content;
create policy "Public read site content" on public.site_content for select to anon, authenticated using (true);
drop policy if exists "Authenticated insert site content" on public.site_content;
create policy "Authenticated insert site content" on public.site_content for insert to authenticated with check (true);
drop policy if exists "Authenticated update site content" on public.site_content;
create policy "Authenticated update site content" on public.site_content for update to authenticated using (true) with check (true);

grant select on public.site_content to anon;
grant select, insert, update on public.site_content to authenticated;

